/**
 * pixel-agents-secure (local): the words the viewer shows for an agent's
 * session signals (agentSignals.ts). Pure, and typed only structurally, so it
 * is tested without a browser.
 */

/** What these helpers read of an agent's state (agentStatus.ts). */
export interface StatusLike {
  tone: 'permission' | 'input' | 'active' | 'done' | 'idle';
}

/** What these helpers read of an activity entry (agentActivity.ts). */
export interface EntryLike {
  t: number;
}

export interface AgentSignals {
  permissionMode?: string;
  /** Set with /rename. */
  title?: string;
  /** Generated by Claude Code from the prompt; only sent with the conversation view on. */
  aiTitle?: string;
  errorStreak: number;
  rateLimited: boolean;
  quotaUntil?: number;
  repeats: number;
}

/** The viewer's opt-in features (the "Novidades" options). */
export interface ViewerFeatures {
  sessionTitle: boolean;
  idleTime: boolean;
  signals: boolean;
  permissionMode: boolean;
  inbox: boolean;
}

export const NO_FEATURES: ViewerFeatures = {
  sessionTitle: false,
  idleTime: false,
  signals: false,
  permissionMode: false,
  inbox: false,
};

/** A turn running this long with nothing new reads as stalled. */
export const STALLED_AFTER_MS = 10 * 60_000;

/** The title to show for a session, when that option is on. */
export function sessionTitle(s: AgentSignals | undefined, features: ViewerFeatures): string | undefined {
  if (!features.sessionTitle || !s) return undefined;
  return s.title ?? s.aiTitle;
}

/** Plain words for a permission mode. */
export function permissionModeText(mode: string): string {
  switch (mode) {
    case 'bypassPermissions':
      return 'sem pedir permissão (bypass)';
    case 'dontAsk':
      return 'não pergunta (dontAsk)';
    case 'auto':
      return 'automático';
    case 'acceptEdits':
      return 'aceita edições';
    case 'plan':
      return 'planejamento';
    case 'default':
      return 'padrão';
    default:
      return mode;
  }
}

export type BadgeTone = 'warn' | 'alert' | 'info';

export interface SignalBadge {
  key: string;
  text: string;
  tone: BadgeTone;
}

function clock(t: number): string {
  return new Date(t).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
}

/** What is worth flagging about an agent right now, most urgent first. */
export function signalBadges(
  s: AgentSignals | undefined,
  status: StatusLike,
  lastEntry: EntryLike | undefined,
  features: ViewerFeatures,
  now: number,
): SignalBadge[] {
  const out: SignalBadge[] = [];
  if (features.signals && s) {
    if (s.rateLimited) {
      out.push({
        key: 'quota',
        tone: 'alert',
        text: s.quotaUntil ? `Sem cota até ${clock(s.quotaUntil)}` : 'Limite de uso atingido',
      });
    }
    if (s.errorStreak > 0) {
      out.push({ key: 'errors', tone: 'alert', text: `${s.errorStreak} erros seguidos` });
    }
    if (s.repeats > 0) {
      out.push({ key: 'loop', tone: 'warn', text: `Mesma chamada ${s.repeats}× seguidas` });
    }
  }
  if (features.signals && status.tone === 'active' && lastEntry && now - lastEntry.t > STALLED_AFTER_MS) {
    out.push({ key: 'stalled', tone: 'warn', text: `Sem novidade há ${Math.round((now - lastEntry.t) / 60_000)} min` });
  }
  if (features.permissionMode && s?.permissionMode) {
    const risky = s.permissionMode === 'bypassPermissions' || s.permissionMode === 'dontAsk';
    out.push({
      key: 'mode',
      tone: risky ? 'alert' : 'info',
      text: `Modo: ${permissionModeText(s.permissionMode)}`,
    });
  }
  return out;
}

export const BADGE_COLOR: Record<BadgeTone, string> = {
  alert: 'var(--color-status-error)',
  warn: 'var(--color-status-permission)',
  info: 'var(--color-text-muted)',
};

/** "parado há 12 min" for an agent with nothing running, when that option is on. */
export function idleText(
  status: StatusLike,
  lastEntry: EntryLike | undefined,
  features: ViewerFeatures,
  now: number,
): string | undefined {
  if (!features.idleTime || !lastEntry || status.tone === 'active' || status.tone === 'permission') {
    return undefined;
  }
  const minutes = Math.floor((now - lastEntry.t) / 60_000);
  if (minutes < 1) return undefined;
  return minutes < 60 ? `parado há ${minutes} min` : `parado há ${Math.floor(minutes / 60)} h ${minutes % 60} min`;
}
